 func windowWillClose(_ notification:Notification){if notification.object as? NSWindow === window {detailVisible=false;window?.contentView=nil;window=nil}}
 func showWindow(){detailVisible=true;if window==nil{let w=NSWindow(contentRect:NSRect(x:0,y:0,width:1040,height:585),styleMask:[.titled,.closable,.miniaturizable,.resizable],backing:.buffered,defer:false);w.delegate=self;w.title="Weather Observatory";w.contentView=NSHostingView(rootView:WeatherSurface(model:self));w.minSize=NSSize(width:720,height:405);w.isReleasedWhenClosed=false;w.center();window=w};window?.makeKeyAndOrderFront(nil);NSApp.activate(ignoringOtherApps:true)}
 func showSettings(_ page:String="Location"){tab=page;if settingsWindow==nil {let w=NSWindow(contentRect:NSRect(x:0,y:0,width:880,height:680),styleMask:[.titled,.closable,.resizable],backing:.buffered,defer:false);w.title="Weather Observatory Settings";w.contentView=NSHostingView(rootView:ObservatoryView(model:self,settingsOnly:true));w.minSize=NSSize(width:740,height:560);w.isReleasedWhenClosed=false;w.center();settingsWindow=w};settingsWindow?.makeKeyAndOrderFront(nil);NSApp.activate(ignoringOtherApps:true)}
 func saveWindyKey(_ value:String){let key=value.trimmingCharacters(in:.whitespacesAndNewlines);guard key.range(of:#"^[A-Za-z0-9_-]{20,160}$"#,options:.regularExpression) != nil else{windyMessage="Enter a valid Map Forecast API key.";return};do{try WindyKey.save(key);connectWindy()}catch{windyMessage="Could not save the key in Keychain."}}
 func removeWindyKey(){do{try WindyKey.remove()}catch{windyMessage="Could not remove the key from Keychain.";return};hasWindyKey=false;windyURL="";windyMessage="Windy disconnected.";windyRequest=UUID().uuidString;try? worker.send(["id":windyRequest!,"action":"windy","key":""]);publish()}
 func connectWindy(){guard windyRequest==nil else{return};guard let key=WindyKey.read(),!key.isEmpty else{hasWindyKey=false;return};hasWindyKey=true;windyMessage="Preparing Windy maps…";let id=UUID().uuidString;windyRequest=id;do{try worker.send(["id":id,"action":"windy","key":key])}catch{windyRequest=nil;windyMessage="Could not start the map connection."};publish()}
