 private func receive(_ m:PluginMessage){guard m.pluginID==moduleID else{return};if session==nil{guard m.type=="hello" else{return};session=m.session;hostFeatures=Set(m.features ?? []);emit("ready",features:["actions-v1","dashboard-v1","panels-v1","diagrams-v1"]+["custom-views-v1","view-resources-v1","isolated-frames-v1","https-frames-v1"].filter{hostFeatures.contains($0)});send(.init(.register,registration:.init(actions:[.init("read_status",title:"Read weather status",output:.init([.init("location",.string),.init("message",.string),.init("available",.boolean)]))],channels:[.init("status",title:"Weather status",kind:.state,schema:.init([.init("location",.string),.init("message",.string),.init("available",.boolean)]))])));refresh();return};guard m.session==session else{return};if m.type=="visibility"{visible=m.visible ?? false};if m.type=="action"{switch m.action{case "configure":showSettings();case "details":showWindow();case "map":tab="Map";showWindow();case "refresh":refresh();default:break}};if m.type=="viewEvent",let event=m.viewEvent{try? handleViewEvent(event)};if m.type=="viewResourceCancel",let id=m.viewResourceCancel{resourceTasks.removeValue(forKey:id)?.cancel()};if m.type=="viewResource",hostFeatures.contains("view-resources-v1"),let request=m.viewResource,resourceTasks[request.id]==nil,resourceTasks.count<48{resourceTasks[request.id]=Task{@MainActor [weak self] in guard let self else{return};let result:PluginViewResourceResult;do{result=try await self.resource(request)}catch{result = .init(id:request.id,error:"Map imagery unavailable. Try again later.")};if !Task.isCancelled{self.emit("viewResourceResult",viewResourceResult:result)};self.resourceTasks[request.id]=nil}};if let b=m.bus,m.type=="bus",b.operation == .execute{let valid=b.address?.name=="read_status" && b.address?.plugin==moduleID;send(.init(.update,requestID:b.requestID,update:.init(valid ? .succeeded:.failed,values:valid ? values:[:])))} }
